KG42.register("rules-1b6de51c9397f994272fd841",{"id":"19-two_stage_battery_sharing::v141-c-R001","paper":"19-two_stage_battery_sharing","record":{"rule_id":"v141-c-R001","mechanism_id":"v141-a-M01","name":"Local market coordinator","process_stage":"coordination","market_meaning":"The ESC is responsible for exporting power to or importing power from the main grid to ensure the community's power balance. Scope: ESC responsibility at the community's interface with the main grid in the P2P sharing mechanism. The ESC is responsible for controlling the charging and discharging activities of all batteries and provides control signals to the battery controllers through one-way communication. Scope: ESC-operated aggregated battery control in the P2P sharing community. Under this shared-responsibility rule, the ESC provides each individual battery controller with the same control signal. Scope: The adopted shared-responsibility rule for community battery control. Condition: Battery charging/discharging power normalized to each battery's nominal capacity is assumed to be the same.","independence_rationale":"Relations governed by the approved function coordination.local_operator under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["coordination.local_operator"],"E":[],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"ESC responsibility at the community's interface with the main grid in the P2P sharing mechanism. | ESC-operated aggregated battery control in the P2P sharing community. | The adopted shared-responsibility rule for community battery control.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e004","v141-b-g02-E15"]},"x":[{"variable_id":"v141-c-R001-x001","symbol":"P_{BC,t}^{i}","meaning":"Charging power of the ith battery at time t, controlled by the ESC through the shared-responsibility battery control signal.","kind":"operational","domain":"Nonnegative real charging power (kW) within the source-stated inverter limit (Eq. (7)).","unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e011","v141-b-g02-E15"]},{"variable_id":"v141-c-R001-x002","symbol":"P_{BD,t}^{i}","meaning":"Discharging power of the ith battery at time t, controlled by the ESC through the shared-responsibility battery control signal.","kind":"operational","domain":"Nonnegative real discharging power (kW) within the source-stated inverter limit (Eq. (7)).","unit":"kW","indices":["i","t"],"evidence_ids":["v141-b-g01-e009","v141-b-g01-e011","v141-b-g02-E15"]}],"theta":[{"parameter_id":"v141-c-R001-theta001","symbol":"W_{B,N}^{i}","meaning":"Nominal capacity (battery size) of the ith battery, used as the normalization basis for the shared-responsibility control rule.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["i"],"evidence_ids":["v141-b-g01-e010","v141-b-g02-E15"]}],"phi":[{"constraint_id":"v141-c-R001-C001","kind":"procedural","role":"core","statement":"The ESC is responsible for exporting power to or importing power from the main grid to ensure the community's power balance. Scope: ESC responsibility at the community's interface with the main grid in the P2P sharing mechanism.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e004"]},{"constraint_id":"v141-c-R001-C002","kind":"procedural","role":"core","statement":"The ESC is responsible for controlling the charging and discharging activities of all batteries and provides control signals to the battery controllers through one-way communication. Scope: ESC-operated aggregated battery control in the P2P sharing community.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e002","v141-b-g01-e004"]},{"constraint_id":"v141-c-R001-C003","kind":"procedural","role":"core","statement":"Under this shared-responsibility rule, the ESC provides each individual battery controller with the same control signal. Scope: The adopted shared-responsibility rule for community battery control. Condition: Battery charging/discharging power normalized to each battery's nominal capacity is assumed to be the same.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E15"]},{"constraint_id":"v141-c-R001-C004","kind":"mathematical","role":"core","statement":"Under the shared-responsibility rule, charging power normalized by nominal capacity is equal across prosumer batteries, and discharging power normalized by nominal capacity is equal across prosumer batteries, at each time slot.","expression":"\\frac{P_{BC,t}^{i}}{W_{B,N}^{i}}=\\frac{P_{BC,t}^{j}}{W_{B,N}^{j}},\\qquad \\frac{P_{BD,t}^{i}}{W_{B,N}^{i}}=\\frac{P_{BD,t}^{j}}{W_{B,N}^{j}},\\quad \\forall i,j\\in\\{1,\\ldots,N_B\\},\\ \\forall t\\in\\{1,\\ldots,T\\}","formalization_origin":"source","template_id":null,"members":["coordination.local_operator"],"variable_refs":["v141-c-R001-x001","v141-c-R001-x002"],"parameter_refs":["v141-c-R001-theta001"],"evidence_ids":["v141-b-g02-E15"]}],"pi":[{"evidence_id":"v141-b-g01-e002","location":{"location_id":"src-b91cee592e-p04-c1r3__v141-a-M01-coordination","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"surplus PV power from prosumers can also be traded with consumers who do not have PV systems. PP A t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"A third party entity named “energy sharing coordinator (ESC)” coordinates between customers and provides P2P sharing services, i.e. assuring the power balance and payment balance [13]. The ESC is the controller of the DERs as well as the local market operator. The ESC is located at the PCC (e.g. the low voltage substation). A smart meter is installed at the PCC, measuring the real-time net power consumption of the community, and this measurement is the input of the ESC. The ESC is communicated with the controllers of these small-scale batteries at the prosumer premises, and provides control signals to them via one-way communication. Through managing the battery charging/discharging, the ESC ensures the maximum use of local energy resources and the minimum amount of electricity fed back into the grid. Therefore the overall energy cost of the community is reduced, and the reduced cost is distributed to individual customers through a P2P pricing mechanism. The ESC also calculates energy bills of individual customers based on the P2P pricing mechanism, using the recorded import/export energy (e.g. half-hourly) from smart meters at the premises."},{"evidence_id":"v141-b-g01-e004","location":{"location_id":"src-b91cee592e-p04-c1r4__v141-a-M01-coordination","page":4,"printed_page":"264","section":"2.1. P2P energy sharing structure","anchor_text":"Details of the control framework and the pricing mechanism for the local market are presented in Sec","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"(1) Energy sharing coordinator (ESC)\n• Export power to (or import power from) the main grid to ensure the power balance of the community;\n• Contract with a supplier for the electricity trade at pre-defined exporting/importing prices and ensure the payment balance between the community and the supplier;\n• Control the charging/discharging activities of all batteries;\n• Contract with individual prosumers and consumers according to the P2P pricing mechanism and ensure the prosumers’ income balance with the consumers’ expenditure."},{"evidence_id":"v141-b-g02-E15","location":{"location_id":"src-b91cee592e-p07-c2r2__v141-a-M01-clearing","page":7,"printed_page":null,"section":null,"anchor_text":"y g g their batteries. By taking the shared responsibility, the battery charging/dischar- ging power","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"A rule was taken that when the community has surplus energy, the prosumers share their responsibilities by charging their batteries in an amount which is in a linear relation to the size (i.e. nominal capacity) of their batteries. Vice versa, when the community consumes electricity, the prosumers share their responsibility by discharging their batteries in an amount which is linear to the size of their batteries. By taking the shared responsibility, the battery charging/discharging power normalized to the nominal capacity of each battery was assumed to be the same. Therefore, the ESC provides each individual battery controller with the same control signal. This means that all batteries are approximately at the same SOC. In practice, some batteries reach the maximum or minimum SOC earlier than others, due to differences in the aging conditions of batteries and inverters. However, this does not affect the control strategy as the control signal depends on the real time measurement at the PCC. The battery controller only receives control signals from the ESC, disregarding the prosumer's own net load. For example, a battery can be discharging whilst the prosumer has surplus PV generation. This is because the energy is required and consumed by his neighbors."},{"evidence_id":"v141-b-g01-e009","location":{"location_id":"src-b91cee592e-p05-c1r2__v141-a-M01-clearing","page":5,"printed_page":"265","section":"2.3. Modelling of battery systems","anchor_text":"Energy sharing Grid inverter kW coordinator Load Load C kW/kWh Meter kW/kWh Meter Main grid kW/kWh p","equation_id":"4","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"W_{B,t}^{i} = W_{B,t-\\Delta t}^{i} * (1-\\sigma_{SD,t}^{i}) + \\left( P_{BC,t}^{i}\\eta_{BC,t}^{i} - \\frac{P_{BD,t}^{i}}{\\eta_{BD,t}^{i}} \\right) * \\Delta t \\qquad (4)\nwhere W_{B,t-\\Delta t}^{i} and W_{B,t}^{i} are the stored energy at time t-\\Delta t and t. \\sigma_{SD,t}^{i} is the self-discharge rate. P_{BC,t}^{i} and P_{BD,t}^{i} are the charging and discharging power at time t. \\eta_{BC,t}^{i} and \\eta_{BD,t}^{i} are the charging and discharging efficiencies. \\Delta t is the length of each time step.\nThe self-discharge of the battery was neglected, and hence \\sigma_{SD,t}^{i} is taken as zero. The battery charging and discharging efficiencies are taken as constant values, neglecting the dependence of the efficiency on the charging or discharging power, the temperature and the battery age [34]."},{"evidence_id":"v141-b-g01-e010","location":{"location_id":"src-b91cee592e-p05-c1r3__v141-a-M01-clearing","page":5,"printed_page":"265","section":"2.3. Modelling of battery systems","anchor_text":"taken as constant values, neglecting the dependence of the eﬃciency on ba the charging or dischargin","equation_id":"5","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"SOC_{t}^{i} = \\frac{W_{B,t}^{i}}{W_{B,N}^{i}} * 100\\%, \\qquad (5)\nwhere W_{B,N}^{i} is the nominal capacity of the battery (i.e. battery size), and the SOC is presented in percentage."},{"evidence_id":"v141-b-g01-e011","location":{"location_id":"src-b91cee592e-p05-c1r3__v141-a-M01-clearing","page":5,"printed_page":"265","section":"2.3. Modelling of battery systems","anchor_text":"taken as constant values, neglecting the dependence of the eﬃciency on ba the charging or dischargin","equation_id":"6-7","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"SOC_{min}^{i} \\leqslant SOC_{t}^{i} \\leqslant SOC_{max}^{i}, \\qquad (6)\n0 \\leqslant P_{BC,t}^{i} \\leqslant P_{BC,max}^{i}, \\quad 0 \\leqslant P_{BD,t}^{i} \\leqslant P_{BD,max}^{i} \\qquad (7)\nwhere SOC_{min}^{i} and SOC_{max}^{i} are the minimum and maximum allowable SOC, and P_{BC,max}^{i} and P_{BD,max}^{i} are the maximum charging and discharging power. In this work, lithium-ion batteries were considered. The SOC of individual batteries was restricted to a range between 20 and 80% of the nominal capacity [34]. The battery charging and discharging power normalized to the nominal capacity assumed to be 1 kW/kWh."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation"],"extras":{"decision_anchor":"coordination.local_operator","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e004","quote":"(1) Energy sharing coordinator (ESC)\n• Export power to (or import power from) the main grid to ensure the power balance of the community;"}],[{"evidence_id":"v141-b-g01-e004","quote":"• Control the charging/discharging activities of all batteries;"},{"evidence_id":"v141-b-g01-e002","quote":"The ESC is communicated with the controllers of these small-scale batteries at the prosumer premises, and provides control signals to them via one-way communication."}],[{"evidence_id":"v141-b-g02-E15","quote":"By taking the shared responsibility, the battery charging/discharging power normalized to the nominal capacity of each battery was assumed to be the same. Therefore, the ESC provides each individual battery controller with the same control signal."}]],"C2_formalization":{"graph_sha256":"9a47773205d25ddd50c491cd4ee6d1d0683401bb2e9aed4de37b4b75d9a618ae","applicability":"formalized","reason":"The frozen graph contains only coordination.local_operator and no edges. The ESC's procedural responsibilities are preserved as not_formalized. The source-supported shared-responsibility condition is formalized as equality of nominal-capacity-normalized charging and discharging power across prosumer batteries, with the operational power variables and nominal-capacity parameter bound to the local-operator coordination node. No additional graph edges are asserted.","bindings":[{"object_id":"v141-c-R001-x001","node_ids":["coordination.local_operator"],"edge_ids":[],"rationale":"The ESC controls the charging/discharging activities of all batteries and sends control signals to individual battery controllers; P_BC is the charging power under that coordination role."},{"object_id":"v141-c-R001-x002","node_ids":["coordination.local_operator"],"edge_ids":[],"rationale":"The ESC controls the charging/discharging activities of all batteries and sends control signals to individual battery controllers; P_BD is the discharging power under that coordination role."},{"object_id":"v141-c-R001-theta001","node_ids":["coordination.local_operator"],"edge_ids":[],"rationale":"Nominal battery capacity is the fixed battery-size basis used by the ESC's shared-responsibility normalization rule."},{"object_id":"v141-c-R001-C004","node_ids":["coordination.local_operator"],"edge_ids":[],"rationale":"The equality across batteries is the formal content of the ESC's common shared-responsibility control signal at the coordination node."}],"revision_requests":[]}},"quarantined_references":[]}});
